+// Shortcuts that make work look done. The scan reads only the run's own changes, so it says what the
+// run did, not what the model claims. Findings are flags for the receipt, never a refusal.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; detail?: string };
+
+const TEST_PATH = /(^|\/)(tests?|__tests__)\/|\.(test|spec)\.[jt]sx?$|_test\.(go|py)$|(^|\/)test_[^/]*\.py$/;
+const CODE_PATH = /\.(m?[jt]sx?|cjs|py|go|rs|rb|java|kt|cs|php|swift|cc|cpp|c|h|hpp)$/;
+const ASSERT = /\bexpect\(|\bassert/;
+const SKIP = /\b(test|it|describe|suite)\.skip\(|\b(xit|xdescribe|xtest)\(|\bt\.Skip(Now)?\(|@pytest\.mark\.skip|\bpytest\.skip\(/;
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', /@ts-(ignore|nocheck)\b|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b|#\s*pylint:\s*disable|\/\/\s*nolint\b/],
+  ['swallowed-error', /catch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*pass\b/],
+  ['type-escape', /\bas any\b|<any>/],
+  ['stub', /not implemented|NotImplementedError|\btodo!\(|unimplemented!\(/i],
+];
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    if (TEST_PATH.test(c.path)) {
+      if (c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+      else if (c.added.filter((l) => ASSERT.test(l)).length < c.removed.filter((l) => ASSERT.test(l)).length) out.push({ rule: 'test-weakened', path: c.path });
+      if (!c.deleted) for (const l of c.added) if (SKIP.test(l)) out.push({ rule: 'test-skipped', path: c.path, detail: l.trim() });
+    }
+    if (c.deleted || !CODE_PATH.test(c.path)) continue;
+    for (const l of c.added)
+      for (const [rule, re] of LINE_RULES) if (re.test(l)) out.push({ rule, path: c.path, detail: l.trim() });
+  }
+  return out;
+}
+
+export const flagOf = (f: Finding) => `${f.rule} ${f.path}${f.detail ? `: ${f.detail}` : ''}`;
+
+// Parses a `git diff -U0` patch. A file's header runs until its first hunk; inside hunks, +/- lines are changes.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk) {
+      if (line.startsWith('+')) cur.added.push(line.slice(1));
+      else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+    } else if (line.startsWith('deleted file mode')) cur.deleted = true;
+  }
+  return out;
+}
