--- a/src/core/trust/slop.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/src/core/trust/slop.ts	2026-10-28 07:31:42.873250266 +0000
@@ -0,0 +1,80 @@
+import type { Snapshots } from '../safety/snapshot.ts';
+import type { EventOf, SessionEvent } from '../types.ts';
+
+// Shortcuts that make work look done. Each finding is one added line (or one deleted test file) in the run's changes.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; detail?: string };
+
+const CODE = /\.(m?[jt]sx?|py|go|rs|rb|java|kt|cs|php|swift|c|h|cc|cpp)$/;
+const TEST = /\.test\.|\.spec\.|_test\.|(^|\/)tests?\/|(^|\/)test_[^/]*$/;
+const ASSERT = /\bassert|\bexpect\(|\bshould\b|assertEqual|\bt\.(Error|Fatal)f?\(/;
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', /@ts-(ignore|expect-error|nocheck)\b|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b|#\s*pylint:\s*disable|\/\/\s*nolint\b/],
+  ['swallowed-error', /\bcatch\s*(\([^)]*\))?\s*\{\s*\}|^\s*except\b[^:]*:\s*pass\s*$/],
+  ['type-escape', /\bas any\b|<any>/],
+  ['stub', /throw new Error\(\s*['"`]not implemented|raise NotImplementedError|\btodo!\(\)|\bunimplemented!\(\)/i],
+];
+const SKIP = /\b(test|it|describe|context|suite)\.skip\(|\bxit\(|\bxdescribe\(|\bxtest\(|\bt\.Skipf?\(|@pytest\.mark\.skip|@unittest\.skip|#\[ignore\]/;
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    if (c.deleted) {
+      if (TEST.test(c.path)) out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (!CODE.test(c.path)) continue;
+    if (TEST.test(c.path)) {
+      if (c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length) out.push({ rule: 'test-weakened', path: c.path });
+      for (const line of c.added) if (SKIP.test(line)) out.push({ rule: 'test-skipped', path: c.path, detail: line.trim().slice(0, 120) });
+    }
+    for (const line of c.added)
+      for (const [rule, re] of LINE_RULES) if (re.test(line)) out.push({ rule, path: c.path, detail: line.trim().slice(0, 120) });
+  }
+  return out;
+}
+
+export const flagOf = (f: Finding) => (f.detail ? `${f.rule} ${f.path}: ${f.detail}` : `${f.rule} ${f.path}`);
+
+// Parses a git patch made with -U0 (or any unified diff): hunk lines count as content, headers do not.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// What the run changed: the snapshot diff from its first tree to its last (bash included) when snapshots are on,
+// otherwise the edit and write calls that completed.
+export function changesOf(events: SessionEvent[], snapshots?: Snapshots): FileChange[] {
+  const snaps = events.filter((e): e is EventOf<'snapshot'> => e.kind === 'snapshot');
+  if (snapshots && snaps.length) return changesFromPatch(snapshots.patch(snaps[0]!.tree, snaps.at(-1)!.tree));
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  const out: FileChange[] = [];
+  const lines = (s: unknown) => String(s ?? '').split('\n');
+  for (const e of events) {
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const intent = intents.get(e.callId);
+    if (!intent) continue;
+    const path = String(intent.input.path ?? '');
+    if (intent.tool === 'write') out.push({ path, added: lines(intent.input.content), removed: [], deleted: false });
+    if (intent.tool === 'edit') {
+      const edits = Array.isArray(intent.input.edits) ? (intent.input.edits as { old_text?: string; new_text?: string }[]) : [];
+      for (const x of edits) out.push({ path, added: lines(x.new_text), removed: lines(x.old_text), deleted: false });
+    }
+  }
+  return out;
+}
