@@ -0,0 +1,71 @@
+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+import { slugify, uniqueSlug } from '../src/slug.ts';
+import { LRU, type EvictReason } from '../src/lru.ts';
+
+test('parseDuration rules', () => {
+  expect(parseDuration(' 2d 4h ')).toBe(187_200_000);
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('1m30s')).toBe(90_000);
+  expect(() => parseDuration('')).toThrow('""');
+  expect(() => parseDuration('10')).toThrow('"10"');
+  expect(() => parseDuration('h')).toThrow('"h"');
+  expect(() => parseDuration('-1s')).toThrow('"-1s"');
+});
+
+test('formatDuration rules', () => {
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(90_000_000)).toBe('1d1h');
+  expect(() => formatDuration(-1)).toThrow();
+});
+
+test('slugify rules', () => {
+  expect(slugify('Straße Æther Œuvre Øl Łódź Đ')).toBe('strasse-aether-oeuvre-ol-lodz-d');
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('abcdefgh', 5)).toBe('abcde');
+  expect(slugify('a-bcdefgh', 5)).toBe('a');
+  expect(slugify('  --Hi!!  ')).toBe('hi');
+});
+
+test('uniqueSlug rules', () => {
+  expect(uniqueSlug('post', new Set())).toBe('post');
+  expect(uniqueSlug('post', new Set(['post', 'post-2']))).toBe('post-3');
+});
+
+test('LRU rules', () => {
+  let t = 0;
+  const evicted: [string, number, EvictReason][] = [];
+  const c = new LRU<string, number>(2, 100, () => t);
+  c.onEvict = (k, v, r) => evicted.push([k, v, r]);
+  c.set('a', 1);
+  t = 50;
+  c.set('b', 2);
+  expect(c.get('a')).toBe(1); // a is now most recent
+  c.set('c', 3); // evicts b (LRU)
+  expect(evicted).toEqual([['b', 2, 'capacity']]);
+  expect(c.keys()).toEqual(['c', 'a']);
+  t = 149; // a expired at 100 (get does not refresh ttl); c expires at 150
+  expect(c.size).toBe(1);
+  expect(c.delete('c')).toBe(true);
+  expect(evicted[1]).toEqual(['c', 3, 'delete']);
+  t = 150;
+  expect(c.get('a')).toBeUndefined();
+  expect(evicted[2]).toEqual(['a', 1, 'expired']);
+  expect(c.size).toBe(0);
+});
+
+test('LRU expired entries are purged before live ones', () => {
+  let t = 0;
+  const evicted: [string, EvictReason][] = [];
+  const c = new LRU<string, number>(2, 10, () => t);
+  c.onEvict = (k, _v, r) => evicted.push([k, r]);
+  c.set('a', 1);
+  t = 5;
+  c.set('b', 2);
+  t = 10; // a expired, b live
+  c.set('c', 3);
+  expect(evicted).toEqual([['a', 'expired']]);
+  expect(c.keys()).toEqual(['c', 'b']);
+});

